create or replace function opening_balance_validate(p jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare out jsonb;rid bigint;r record;cat text;begin out:=opening_balance_stage(p);rid:=(out->>'runId')::bigint;for r in select l.*,a.category from opening_balance_lines l join chart_accounts a using(account_id)where l.run_id=rid loop update opening_balance_lines set cost_center_id=(select cost_center_id from cost_centers where subsidiary_id=active_subsidiary_id()and code=raw_data->>'costCenter'limit 1),location_id=(select location_id from locations where subsidiary_id=active_subsidiary_id()and(name=raw_data->>'location'or location_id::text=raw_data->>'location')limit 1)where id=r.id;if (select load_type from opening_balance_runs where id=rid)='FISCAL_YEAR'and coalesce(r.category,'')in('Ingreso','Ingresos','Gasto','Gastos','Costo','Costos')then raise exception'Fila %: las cuentas de resultados solo se permiten en apertura a mitad de período.',r.row_number;end if;if coalesce(r.category,'')in('Ingreso','Ingresos','Gasto','Gastos','Costo','Costos')and(coalesce(r.raw_data->>'costCenter','')=''or coalesce(r.raw_data->>'location','')='')then raise exception'Fila %: centro de costo y sucursal son obligatorios para cuentas de resultados.',r.row_number;end if;if coalesce(r.raw_data->>'costCenter','')<>''and not exists(select 1 from cost_centers where subsidiary_id=active_subsidiary_id()and code=r.raw_data->>'costCenter')then raise exception'Fila %: centro de costo inválido.',r.row_number;end if;end loop;update opening_balance_runs set status='VALIDATED'where id=rid;return opening_balance_preview(rid);end$$;
grant execute on function opening_balance_validate(jsonb)to authenticated;notify pgrst,'reload schema';
